def parse_list(self, response):
    rows = response.css('table tbody tr')
    for row in rows:
        title = row.css('td:nth-child(1) a::text').get()
        detail_url = row.css('td:nth-child(1) a::attr(href)').get()
        author = row.css('td:nth-child(2)::text').get()
        date = row.css('td:nth-child(3)::text').get()
        status = row.css('td:nth-child(4)::text').get()
        yield scrapy.Request(
            url=response.urljoin(detail_url),
            callback=self.parse_detail,
            meta={'title': title, 'author': author, 'date': date, 'status': status}
        )
    next_btn = response.css('a.next')
    if next_btn:
        next_url = next_btn.attrib.get('href')
        if next_url:
            yield scrapy.Request(url=response.urljoin(next_url), callback=self.parse_list)
